<?php get_header(); ?><main class="wrap"><header class="archive-header"><h1 class="archive-title"><?php echo is_search()?'Resultados para: '.esc_html(get_search_query()):(is_archive()?get_the_archive_title():'Últimas notícias'); ?></h1><?php the_archive_description('<div class="archive-description">','</div>'); ?></header><section class="news-grid"><?php if(have_posts()):while(have_posts()):the_post();$cat=franklem_first_category(); ?><article class="story-card"><?php if(has_post_thumbnail())the_post_thumbnail('franklem-card'); ?><span class="time"><?php echo esc_html(get_the_date()); ?></span><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(franklem_subtitle()?:get_the_excerpt()); ?></p><a class="read-more" href="<?php the_permalink(); ?>">Ler notícia →</a></article><?php endwhile;the_posts_pagination();else: ?><p class="empty">Nenhuma notícia encontrada.</p><?php endif; ?></section></main><?php get_footer(); ?>
